 breadcrumb([[ $b['title'],route('board',['f'=>$b['id']])],$t['title']]);
 $author=$s['users'][$t['author']]??['name'=>'Удалённый пользователь'];$posts=thread_posts($s,$id);[$list,$pg,$pages]=paged($posts,12);$watched=$u&&in_array($id,$u['watches']??[],true);
 ?><div class="topic-head"><div class="topic-head-main"><span class="eyebrow">ОБСУЖДЕНИЕ · <?=h($b['title'])?></span><h1><?=h($t['title'])?></h1><div class="topic-meta"><?=ico('user',16)?> <?=h($author['name'])?> <span>·</span> <?=ico('clock',16)?> <?=datetime_string($t['created'])?> <span>·</span><?=ico('messages-square',16)?> <?=count($posts)?> сообщ.</div></div><div class="topic-tools"><?php if($t['pinned']):?><span class="status-chip"><?=ico('pin',15)?> Закреплена</span><?php endif;?><?php if($t['locked']):?><span class="status-chip"><?=ico('lock',15)?> Закрыта</span><?php endif;?><?php if($u):?><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="topic_watch"><input type="hidden" name="topic" value="<?=h($id)?>"><button class="btn btn-ghost btn-small" type="submit"><?=ico('bell',16)?> <?=$watched?'Отписаться':'Подписаться'?></button></form><?php endif;?></div></div>
 <div class="content-grid"><div class="main-column"><div class="posts-stack">
 <?php foreach($list as $i=>$post):$poster=$s['users'][$post['author']]??['id'=>'','name'=>'Удалённый пользователь','role'=>'user','joined'=>$post['created']];?><article class="post-card" id="<?=h($post['id'])?>"><div class="post-author"><a href="<?=route('profile',['u'=>$poster['id']])?>" class="post-identity"><?=avatar($poster,64)?><strong><?=h($poster['name'])?></strong></a><?=role_tag($poster)?><small>С нами с <?=date('m.Y',strtotime($poster['joined'].' UTC'))?></small><span class="post-author-accent"></span></div><div class="post-content"><div class="post-toolbar"><span><?=ico('clock',14)?> <?=datetime_string($post['created'])?><?php if($post['edited']):?> · изменено <?=since($post['edited'])?><?php endif;?></span><span class="post-number">#<?=($pg-1)*12+$i+1?></span></div><div class="post-body"><?=bm($post['body'])?></div><div class="post-actions"><?php if(can_edit_post($post,$u)):?><a href="<?=route('edit',['post'=>$post['id']])?>"><?=ico('edit',15)?> Изменить</a><?php endif;?><?php if($u):?><a href="<?=route('report',['post'=>$post['id']])?>"><?=ico('flag',15)?> Жалоба</a><?php endif;?><?php if(can_edit_post($post,$u)&&$post['id']!==$posts[0]['id']):?><form method="post" class="inline-form confirm-form" data-confirm="Удалить сообщение?"><?=csrf_field()?><input type="hidden" name="action" value="post_delete"><input type="hidden" name="post" value="<?=h($post['id'])?>"><button type="submit"><?=ico('trash',15)?> Удалить</button></form><?php endif;?></div></div></article><?php endforeach;?>
 </div><?php paginator($pg,$pages,['p'=>'topic','t'=>$id]);?>
 <?php if($u&&!$u['banned']&&(!$t['locked']||staff($u))):?><div class="panel reply-panel"><div class="panel-title"><h3>Написать ответ</h3><?=ico('message-square',20)?></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reply_create"><input type="hidden" name="topic" value="<?=h($id)?>"><?php form_textarea('Твоё сообщение','body','',12000,6);?><div class="form-foot"><small>Можно использовать [b]жирный[/b], [i]курсив[/i] и ссылки.</small><button class="btn btn-primary" type="submit"><?=ico('send',17)?> Отправить</button></div></form></div>
 <?php elseif(!$u):?><div class="sign-in-call"><strong>Хочешь присоединиться к обсуждению?</strong><a class="btn btn-primary" href="<?=route('login')?>">Войти на форум</a></div><?php elseif($t['locked']):?><div class="privacy-note"><?=ico('lock',18)?> Эта тема закрыта для ответов.</div><?php endif;?></div>
 <aside class="sidebar"><div class="panel"><div class="panel-title"><h3>Обсуждение</h3><?=ico('messages-square',20)?></div><div class="detail-list"><div><span>Создана</span><b><?=date('d.m.Y',strtotime($t['created'].' UTC'))?></b></div><div><span>Ответов</span><b><?=max(0,count($posts)-1)?></b></div><div><span>Автор</span><b><?=h($author['name'])?></b></div></div><a class="btn btn-outline btn-full" href="<?=route('board',['f'=>$b['id']])?>">Все темы раздела <?=ico('arrow-right',16)?></a></div>
 <?php if(staff($u)||($u && $u['id']===$t['author'])):?><div class="panel"><div class="panel-title"><h3>Управление темой</h3><?=ico('settings',18)?></div><div class="admin-action-stack"><?php if(staff($u)):?><?php foreach([['pin',$t['pinned']?'Открепить':'Закрепить'],['lock',$t['locked']?'Открыть тему':'Закрыть тему']] as $do):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="topic_moderate"><input type="hidden" name="topic" value="<?=h($id)?>"><input type="hidden" name="mode" value="<?=$do[0]?>"><button class="action-link" type="submit"><?=ico($do[0]==='pin'?'pin':'lock',16)?> <?=$do[1]?></button></form><?php endforeach;?><form method="post" class="move-form"><?=csrf_field()?><input type="hidden" name="action" value="topic_moderate"><input type="hidden" name="topic" value="<?=h($id)?>"><input type="hidden" name="mode" value="move"><label class="field"><span>Перенести в раздел</span><select name="destination"><?php foreach($s['boards'] as $bb):?><option value="<?=h($bb['id'])?>" <?=$bb['id']===$b['id']?'selected':''?>><?=h($bb['title'])?></option><?php endforeach;?></select></label><button class="btn btn-outline btn-full" type="submit">Перенести</button></form><?php endif;?><form method="post" class="confirm-form" data-confirm="Удалить всю тему без возможности восстановления?"><?=csrf_field()?><input type="hidden" name="action" value="topic_moderate"><input type="hidden" name="topic" value="<?=h($id)?>"><input type="hidden" name="mode" value="delete"><button class="action-link danger" type="submit"><?=ico('trash',16)?> Удалить тему</button></form></div></div><?php endif;?></aside></div><?php
}
function page_new(array $s,?array $u): void {
 if(!$u){page_auth_gate();return;}$id=(string)($_GET['f']??'');$b=$s['boards'][$id]??null;if(!$b||!can_write_board($b,$u)){http_response_code(403);page_error('Нельзя создать тему','Выберите доступный раздел или проверьте права аккаунта.');return;}
