}
function page_search(array $s,?array $u): void {$q=trim((string)($_GET['q']??''));if(txtlen($q)>90)$q='';$items=[];if(txtlen($q)>=2){foreach(all_visible_topics($s,$u) as $t){$body=implode(' ',array_map(fn($p)=>$p['body'],thread_posts($s,$t['id'])));if(mbpos($t['title'],$q)||mbpos($body,$q))$items[]=$t;}}breadcrumb(['Поиск']);?><div class="page-title-card"><div class="page-title-icon"><?=ico('search',32)?></div><div class="page-title-text"><span class="eyebrow">НАЙДИ НУЖНОЕ</span><h1>Поиск по форуму</h1><p>Поиск по названиям тем и сообщениям</p></div></div><form class="search-form" method="get"><input type="hidden" name="p" value="search"><input name="q" placeholder="Новости, сервер, помощь..." maxlength="90" value="<?=h($q)?>" autofocus><button class="btn btn-primary" type="submit"><?=ico('search',17)?> Найти</button></form><?php if(txtlen($q)>=2):?><div class="content-grid"><div class="main-column"><div class="forum-block"><div class="list-top"><h2>Результаты <span class="list-count"><?=count($items)?></span></h2></div><?php [$slice,$pg,$pages]=paged($items,15);if(!$items):?><div class="empty-state"><strong>Ничего не найдено</strong><p>Попробуй другой запрос.</p></div><?php else:foreach($slice as $t)topic_row($s,$t,true);endif;?></div><?php paginator($pg,$pages,['p'=>'search','q'=>$q]);?></div><?php mini_sidebar($s,$u);?></div><?php else:?><div class="panel"><p class="muted-text">Введи как минимум 2 символа, чтобы найти обсуждения.</p></div><?php endif;?><?php }
function mbpos(string $hay,string $needle): bool {if(function_exists('mb_stripos'))return mb_stripos($hay,$needle,0,'UTF-8')!==false;return str_contains(lower($hay),lower($needle));}
function page_members(array $s,?array $u): void {breadcrumb(['Участники']);$list=array_values($s['users']);usort($list,fn($a,$b)=>strcmp($a['joined'],$b['joined']));?><div class="page-title-card"><div class="page-title-icon"><?=ico('users',32)?></div><div class="page-title-text"><span class="eyebrow">КОМЬЮНИТИ</span><h1>Участники форума</h1><p>Сейчас зарегистрировано <?=count($list)?> аккаунтов</p></div></div><div class="members-grid"><?php [$slice,$pg,$pages]=paged($list,24);foreach($slice as $member):?><a class="member-card" href="<?=route('profile',['u'=>$member['id']])?>"><?=avatar($member,53)?><div><strong><?=h($member['name'])?></strong><?=role_tag($member)?><small>С нами с <?=date('d.m.Y',strtotime($member['joined'].' UTC'))?></small></div><?=ico('chevron-right',17)?></a><?php endforeach;?></div><?php paginator($pg,$pages,['p'=>'members']);?><?php }
function page_profile(array $s,?array $u): void {
 $id=(string)($_GET['u']??($u['id']??''));$member=$s['users'][$id]??null;if(!$member){http_response_code(404);page_error('Профиль не найден','Такого пользователя нет на форуме.');return;}
 $topics=array_values(array_filter(all_visible_topics($s,$u),fn($t)=>$t['author']===$id));$posts=array_values(array_filter($s['posts'],fn($p)=>$p['author']===$id && !($p['deleted']??false) && isset($s['topics'][$p['topic']])&&can_read_topic($s['topics'][$p['topic']],$s['boards'][$s['topics'][$p['topic']]['board']],$u)));
 breadcrumb(['Участник: '.$member['name']]);?><div class="profile-cover"><div class="profile-banner"></div><div class="profile-main"><?=avatar($member,82)?><div><span class="eyebrow">УЧАСТНИК СООБЩЕСТВА</span><h1><?=h($member['name'])?></h1><?=role_tag($member)?><p><?=h($member['bio']?:'Создаёт свою историю в SUNKORA ROLEPLAY.')?></p></div><?php if($u && $u['id']===$id):?><a class="btn btn-outline" href="<?=route('settings')?>"><?=ico('edit',17)?> Редактировать профиль</a><?php endif;?></div></div><div class="profile-stats"><div><strong><?=count($topics)?></strong><span>Создано тем</span></div><div><strong><?=count($posts)?></strong><span>Сообщений</span></div><div><strong><?=date('d.m.Y',strtotime($member['joined'].' UTC'))?></strong><span>Дата регистрации</span></div></div><div class="forum-block"><div class="list-top"><h2>Публикации пользователя</h2></div><?php foreach(array_slice($topics,0,12) as $t)topic_row($s,$t,true);if(!$topics):?><div class="empty-state"><p>Пока нет опубликованных тем.</p></div><?php endif;?></div><?php
}
