function page_auth(string $type,array $state): void { $setup=$type==='setup';$register=$type==='register';?><div class="auth-layout"><div class="auth-art"><div class="auth-art-overlay"></div><div class="auth-art-copy"><span class="eyebrow">SUNKORA ROLEPLAY</span><h2>Это больше,<br>чем просто игра.</h2><p>Твоя история начинается здесь.</p></div></div><div class="panel auth-panel"><div class="auth-welcome"><img src="assets/img/sunkora-avatar.jpg" alt="SUNKORA ROLEPLAY"><span class="eyebrow"><?=$setup?'ПЕРВАЯ УСТАНОВКА':($register?'СТАНЬ ЧАСТЬЮ ИСТОРИИ':'С ВОЗВРАЩЕНИЕМ')?></span><h1><?=$setup?'Создание владельца':($register?'Регистрация':'Войти на форум')?></h1><p><?=$setup?'Ключ установки находится в файле config/install-key.php':($register?'Создай аккаунт для общения на форуме.':'Введи ник и пароль своего форумного аккаунта.')?></p></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="<?=h($type)?>"><?php if($setup)form_input('Ключ установки','install_key','','text',150,true);form_input('Никнейм','name','','text',24,true);form_input('Пароль','password','','password',128,true);if($register)form_input('Повтори пароль','confirm','','password',128,true);?><button class="btn btn-primary btn-full" type="submit"><?=$setup?'Установить форум':($register?'Создать аккаунт':'Войти')?> <?=ico('arrow-right',17)?></button></form><div class="auth-bottom"><?php if($register):?>Есть аккаунт? <a href="<?=route('login')?>">Войти</a><?php elseif(!$setup):?>Впервые на форуме? <a href="<?=route('register')?>">Регистрация</a><?php else:?>Создай администратора и удали ключ из доступных резервных копий.<?php endif;?></div></div></div><?php }
function page_settings(array $s,?array $u): void {if(!$u){page_auth_gate();return;}breadcrumb(['Настройки профиля']);?><div class="page-title-card"><div class="page-title-icon"><?=ico('settings',30)?></div><div class="page-title-text"><span class="eyebrow">ЛИЧНЫЙ КАБИНЕТ</span><h1>Настройки аккаунта</h1><p>Редактируй описание и пароль</p></div></div><div class="settings-grid"><div class="panel"><div class="panel-title"><h3>О себе</h3><?=ico('edit',19)?></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="profile_save"><?php form_textarea('Короткое описание','bio',$u['bio']??'',350,5);?><button class="btn btn-primary" type="submit">Сохранить</button></form></div><div class="panel"><div class="panel-title"><h3>Безопасность</h3><?=ico('lock',19)?></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="password_change"><?php form_input('Текущий пароль','old_password','','password',128,true);form_input('Новый пароль (от 10 символов)','new_password','','password',128,true);?><button class="btn btn-primary" type="submit">Сменить пароль</button></form><div class="splitter"></div><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button type="submit" class="btn btn-outline">Выйти из аккаунта <?=ico('log-out',16)?></button></form></div></div><?php }
