function page_moderation(array $s,?array $u): void {if(!staff($u)){http_response_code(403);page_error('Недостаточно прав','');return;}
 breadcrumb(['Модерация']);$reports=array_values($s['reports']);usort($reports,fn($a,$b)=>strcmp($b['created'],$a['created']));?><div class="page-title-card"><div class="page-title-icon"><?=ico('flag',32)?></div><div class="page-title-text"><span class="eyebrow">ПАНЕЛЬ КОМАНДЫ</span><h1>Жалобы на сообщения</h1><p>Проверяй обращения игроков и управляй нарушениями</p></div><?php if(administrator($u)):?><a class="btn btn-outline" href="<?=route('admin')?>">В админ-панель</a><?php endif;?></div><div class="panel"><div class="list-top"><h2>Обращения <span class="list-count"><?=count(array_filter($reports,fn($r)=>$r['status']==='open'))?> открыто</span></h2></div><?php foreach($reports as $r):$post=$s['posts'][$r['post']]??null;$topic=$post?($s['topics'][$post['topic']]??null):null;?><div class="report-row"><div><span class="role <?=$r['status']==='open'?'role-admin':'role-user'?>"><?=$r['status']==='open'?'Открыта':'Решена'?></span><strong><?=h($r['reason'])?></strong><small><?=h(username($s,$r['by']))?> · <?=datetime_string($r['created'])?></small><?php if($topic):?><a href="<?=route('topic',['t'=>$topic['id']])?>#<?=h($r['post'])?>">К сообщению <?=ico('external-link',14)?></a><?php else:?><span class="muted-text">Сообщение удалено</span><?php endif;?></div><?php if($r['status']==='open'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="report_resolve"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-outline" type="submit"><?=ico('check',16)?> Завершить</button></form><?php endif;?></div><?php endforeach;?><?php if(!$reports):?><div class="empty-state"><strong>Нет жалоб</strong><p>Все обращения обработаны.</p></div><?php endif;?></div><?php }
